# Builds every_node_ec.graph.json: the engine coverage nodes (EC, gen/coverage.rs), each wired so
# the graph checks clean: the events each run a few actions; every pure output goes to a Print
# String; an NPC is made at Map Started and walked about (Move To, Follow Path, Stop).
# Run from this folder: python3 make_every_node_ec.py
import json

nodes, edges = [], []
def N(id, type, params=None, x=0, y=0):
    nodes.append({"id": id, "type": type, "pos": {"x": x * 260, "y": y * 220}, "params": params or {}})
def W(a, ap, b, bp):
    edges.append({"id": f"w{len(edges)+1}", "from": {"node": a, "pin": ap}, "to": {"node": b, "pin": bp}})
def chain(ids, first_pin="then"):
    for a, b in zip(ids, ids[1:]):
        W(a, first_pin if a == ids[0] else "then", b, "exec")

# Player Spawned: damage, properties, HUD, chat, push, jumps, zone and movement reads, radio, MOTD, voice
N("ps", "event.player_spawned", {}, 0, 0)
N("dmg", "damage.deal", {"amount": 5, "kind": "burn", "zone": "head", "armor": True}, 1, 0)
N("pset", "ent.prop_set", {"field": "renderfx", "pick": "fx_glowshell"}, 2, 0)
N("pcol", "ent.prop_set", {"field": "color", "r": 0, "g": 200, "b": 255}, 3, 0)
N("big", "msg.big_hud", {"text": "Go!", "effect": "type", "r": 255, "g": 80, "b": 40}, 4, 0)
N("cc", "msg.color_chat", {"tag": "[EC]", "text": "Hi", "color": "team"}, 5, 0)
N("cc2", "msg.color_chat", {"tag": "", "text": "Green 100%", "color": "green"}, 6, 0)
N("push", "player.push", {"along": "up", "strength": 300}, 7, 0)
N("jr", "player.jump_rules", {"air": 2, "bhop": True, "reset_death": True}, 8, 0)
N("jra", "player.jump_rules", {"noduck": True, "air": 0, "reset_round": True}, 9, 0)
N("radio", "msg.radio", {"line": "go", "to": "all"}, 10, 0)
N("radio2", "msg.radio", {"line": "a_terwin", "to": "t", "text": True}, 11, 0)
N("motd", "msg.info_window", {"title": "Rules", "text": "Hello [b]you[b][br]Have fun <3 & more"}, 12, 0)
N("vo", "player.voice_override", {"how": "hears"}, 13, 0)
N("pr1", "debug.print", {"text": "state", "chat": False}, 14, 0)
N("pr2", "debug.print", {"text": "speed", "chat": False}, 15, 0)
N("pr3", "debug.print", {"text": "zone", "chat": False}, 16, 0)
N("pr4", "debug.print", {"text": "prop", "chat": False}, 17, 0)
N("pr5", "debug.print", {"text": "color", "chat": False}, 18, 0)
chain(["ps", "dmg", "pset", "pcol", "big", "cc", "cc2", "push", "jr", "jra", "radio", "radio2", "motd", "vo", "pr1", "pr2", "pr3", "pr4", "pr5"])
for t, p in [("dmg", "target"), ("dmg", "attacker"), ("pset", "ent"), ("pcol", "ent"), ("big", "player"), ("cc", "player"), ("cc", "of"), ("push", "target"), ("jr", "player"), ("radio", "player"), ("radio", "from"), ("motd", "player"), ("vo", "player")]:
    W("ps", "player", t, p)
N("ms", "player.move_state", {}, 14, 1)
W("ps", "player", "ms", "player")
W("ms", "ground", "pr1", "value")
W("ms", "speed", "pr2", "value")
N("iz", "player.in_zone", {"zone": "bomb"}, 16, 1)
W("ps", "player", "iz", "player")
W("iz", "out", "pr3", "value")
N("pg", "ent.prop_get", {"field": "health"}, 17, 1)
W("ps", "player", "pg", "ent")
W("pg", "value", "pr4", "value")
N("pg2", "ent.prop_get", {"field": "color"}, 18, 1)
W("ps", "player", "pg2", "ent")
W("pg2", "color", "pr5", "value")
N("ms_name", "player.get_name", {}, 5, 1)
W("ps", "player", "ms_name", "player")
W("ms_name", "out", "cc2", "value")
W("ms", "vspeed", "big", "value")
# the rest of Movement State's pins (each read somewhere)
for k, pin in enumerate(["duck", "water", "level", "ladder"]):
    pid = f"prm{k}"
    N(pid, "debug.print", {"text": pin, "chat": False}, 19 + k, 0)
    W("pr5" if k == 0 else f"prm{k-1}", "then", pid, "exec")
    W("ms", pin, pid, "value")

# Map Started: objectives, voice, map type, an NPC and its walks, a prop to attach and animate
N("mst", "event.map_started", {}, 0, 3)
N("noobj", "game.remove_objectives", {"buy": False}, 1, 3)
N("voice", "game.voice_rules", {"who": "team_life", "dist": 1500}, 2, 3)
N("mt", "game.map_type", {}, 3, 4)
N("prt", "debug.print", {"text": "map", "chat": False}, 3, 3)
W("mt", "type", "prt", "value")
mt_pins = ["bomb", "hostage", "vip", "escape"]
prev = "prt"
for k, pin in enumerate(mt_pins):
    pid = f"prt{k}"
    N(pid, "debug.print", {"text": pin, "chat": False}, 4 + k, 3)
    W(prev, "then", pid, "exec")
    W("mt", pin, pid, "value")
    prev = pid
N("v1", "vec.make", {"x": 0, "y": 0, "z": 0}, 8, 4)
N("v2", "vec.make", {"x": 128, "y": 0, "z": 0}, 8, 5)
N("v3", "vec.make", {"x": 128, "y": 128, "z": 0}, 8, 6)
N("npc", "npc.spawn", {"model": "models/barney.mdl", "name": "Walker"}, 8, 3)
W("v1", "out", "npc", "pos")
N("mv", "npc.move_to", {"speed": "run", "stay": True}, 9, 3)
W("npc", "out", "mv", "npc")
W("v2", "out", "mv", "pos")
N("arr", "debug.print", {"text": "arrived", "chat": True}, 10, 2)
N("fail", "debug.print", {"text": "failed", "chat": True}, 10, 4)
W("mv", "arrived", "arr", "exec")
W("mv", "failed", "fail", "exec")
N("mk", "array.make", {"of": "vector", "count": 2}, 10, 5)
W("v2", "out", "mk", "i0")
W("v3", "out", "mk", "i1")
N("fp", "npc.follow_path", {"loop": False}, 11, 2)
W("arr", "then", "fp", "exec")
W("npc", "out", "fp", "npc")
W("mk", "out", "fp", "points")
N("atp", "debug.print", {"text": "at point", "chat": False}, 12, 1)
N("fin", "debug.print", {"text": "finished", "chat": True}, 12, 2)
W("fp", "point", "atp", "exec")
W("fp", "finished", "fin", "exec")
N("fp2", "npc.follow_path", {"track": "path1", "loop": True, "speed": "walk"}, 12, 4)
W("fail", "then", "fp2", "exec")
W("npc", "out", "fp2", "npc")
N("stop", "npc.stop", {"stay": True}, 13, 4)
W("fp2", "failed", "stop", "exec")
W("npc", "out", "stop", "npc")
N("prop", "ent.spawn_prop", {"model": "models/w_c4.mdl", "solid": False}, 9, 6)
N("anim", "ent.play_anim", {"sequence": "idle", "loop": True, "length": 1.5}, 10, 6)
N("att", "ent.attach", {"point": "origin"}, 11, 6)
N("att2", "ent.attach", {"point": "a0", "on_death": False}, 12, 6)
N("det", "ent.detach", {"fall": True}, 13, 6)
N("pset2", "ent.prop_set", {"field": "scale", "value": 2}, 14, 6)
W("npc", "out", "prop", "at")
W("prop", "out", "anim", "ent")
W("prop", "out", "att", "ent")
W("npc", "out", "att", "to")
W("v2", "out", "att", "offset")
W("prop", "out", "att2", "ent")
W("npc", "out", "att2", "to")
W("prop", "out", "det", "ent")
W("prop", "out", "pset2", "ent")
chain(["mst", "noobj", "voice", "prt"])
W(prev, "then", "npc", "exec")
chain(["npc", "mv"])
W("mv", "then", "prop", "exec")
chain(["prop", "anim", "att", "att2", "det", "pset2"])

# Grenade Thrown: shorter fuse, a push; Exploded: damage at the thrower
N("gt", "event.grenade_thrown", {"type": "he"}, 0, 8)
N("fuse", "ent.grenade_fuse", {"secs": 0.5}, 1, 8)
N("gpush", "player.push", {"along": "dir", "strength": 200}, 2, 8)
N("gprt", "debug.print", {"text": "thrown", "chat": False}, 3, 8)
chain(["gt", "fuse", "gpush", "gprt"])
W("gt", "grenade", "fuse", "grenade")
W("gt", "grenade", "gpush", "target")
W("gt", "pos", "gpush", "dir")
W("gt", "kind", "gprt", "value")
N("ge", "event.grenade_exploded", {}, 0, 9)
N("gprt2", "debug.print", {"text": "boom", "chat": False}, 1, 9)
N("gpush2", "player.push", {"along": "away", "strength": 400, "lift": 200, "how": "replace"}, 2, 9)
chain(["ge", "gprt2", "gpush2"])
W("ge", "kind", "gprt2", "value")
W("ge", "player", "gpush2", "target")
W("ge", "pos", "gpush2", "point")
N("gprt3", "debug.print", {"text": "grenade", "chat": False}, 3, 9)
W("gpush2", "then", "gprt3", "exec")
W("ge", "grenade", "gprt3", "value")
N("gprt4", "debug.print", {"text": "thrower", "chat": False}, 4, 8)
W("gprt", "then", "gprt4", "exec")
W("gt", "player", "gprt4", "value")

# On Map Entity Fired, Weapon Switched, zones
N("mf", "event.map_fired", {"name": ""}, 0, 11)
N("mfp", "debug.print", {"text": "fired", "chat": False}, 1, 11)
N("mfp2", "debug.print", {"text": "by", "chat": False}, 2, 11)
N("mfp3", "debug.print", {"text": "ent", "chat": False}, 3, 11)
N("mfp4", "debug.print", {"text": "caller", "chat": False}, 4, 11)
chain(["mf", "mfp", "mfp2", "mfp3", "mfp4"])
W("mf", "name", "mfp", "value")
W("mf", "activator", "mfp2", "value")
W("mf", "entity", "mfp3", "value")
W("mf", "caller", "mfp4", "value")
N("mf2", "event.map_fired", {"name": "door1"}, 0, 12)
N("mf2p", "debug.print", {"text": "door1", "chat": False}, 1, 12)
chain(["mf2", "mf2p"])
N("ws", "event.weapon_switched", {}, 0, 13)
N("wsp", "debug.print", {"text": "new", "chat": False}, 1, 13)
N("wsp2", "debug.print", {"text": "old", "chat": False}, 2, 13)
N("wsp3", "debug.print", {"text": "weapon", "chat": False}, 3, 13)
N("wsp4", "debug.print", {"text": "who", "chat": False}, 4, 13)
chain(["ws", "wsp", "wsp2", "wsp3", "wsp4"])
W("ws", "new", "wsp", "value")
W("ws", "old", "wsp2", "value")
W("ws", "weapon", "wsp3", "value")
W("ws", "player", "wsp4", "value")
N("ze", "event.zone_enter", {"zone": "buy"}, 0, 14)
N("zep", "msg.color_chat", {"tag": "[Zone]", "text": "Buy zone", "color": "blue"}, 1, 14)
chain(["ze", "zep"])
W("ze", "player", "zep", "player")
N("zl", "event.zone_leave", {"zone": "bomb"}, 0, 15)
N("zlp", "msg.big_hud", {"text": "Left the site", "x": 0.1, "y": 0.8, "effect": "flicker"}, 1, 15)
chain(["zl", "zlp"])
W("zl", "player", "zlp", "player")

g = {"schema": "loner-strike/graph", "version": 3, "mode": {"id": "every_node_ec", "name": "Every Node EC", "description": "Engine coverage nodes and NPC moves"},
     "variables": [], "nodes": nodes, "edges": edges}
json.dump(g, open("every_node_ec.graph.json", "w"), indent=1)
print(len(nodes), "nodes", len(edges), "edges")
